using System.IO;

namespace WhisperClient.Core;

/// <summary>
/// Reads the per-install token generated by the local orchestrator. The token
/// is never logged or displayed. Production releases must additionally verify
/// the token file's Windows ACL during installation and diagnostics.
/// </summary>
public sealed class LocalAuthTokenProvider
{
    public string TokenPath { get; }

    public LocalAuthTokenProvider(string? tokenPath = null)
    {
        var configured = Environment.GetEnvironmentVariable("WHISPER_AUTH_TOKEN_FILE");
        TokenPath = tokenPath ?? (!string.IsNullOrWhiteSpace(configured) ? configured : Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "Whisper",
            "orchestrator.token"));
    }

    public string GetToken()
    {
        if (!File.Exists(TokenPath))
            throw new InvalidOperationException(
                "The local orchestrator authentication token is missing. Start WhisperBrain first.");

        var token = File.ReadAllText(TokenPath).Trim();
        if (token.Length < 32)
            throw new InvalidOperationException("The local orchestrator authentication token is invalid.");

        return token;
    }
}
